                    }
                    break;
                case SCHEMA_CHANGE:
                    ProtocolEvent.SchemaChange scc = (ProtocolEvent.SchemaChange)event;
                    switch (scc.change) {
                        case CREATED:
                            if (scc.table.isEmpty())
                                submitSchemaRefresh(null, null);
                            else
                                submitSchemaRefresh(scc.keyspace, null);
                            break;
                        case DROPPED:
                            if (scc.table.isEmpty())
