                    if (extension.name() != null && extension.name().length() > 0) {
                        wrapper = new HashMap<String, Object>();
                        wrapper.put(extension.name(), extensionProperties);
                        resultSet.add(wrapper);
                    } else {
                        resultSet.add(extensionProperties);
