        obstacle.setRoadSegment(id, roadLength);
        addVehicle(obstacle);
    }

    /**
     * Adds a vehicle to this road segment.
     * 
     * @param vehicle
     */
    public void addVehicle(Vehicle vehicle) {
        vehicle.setRoadSegment(id, roadLength);
