        }
        if (json.has("clickEvent")) {
            cc.setClickEvent(ClickEvent.fromJson(json.getAsJsonObject("clickEvent")));
        }
        if (json.has("hoverEvent")) {
            cc.setHoverEvent(HoverEvent.fromJson(json.getAsJsonObject("hoverEvent")));
