    public static final Set<GraphQLScalarType> BSON_SCALARS = Sets.newHashSet(
        GraphQLBsonDocument,
        GraphQLBsonObjectId,
        GraphQLBsonDecimal128,
        GraphQLBsonTimestamp,
        GraphQLBsonDate,
        GraphQLBsonArray,
        GraphQLBsonRegularExpression,
        GraphQLBsonInt64
    );

    public static Map<String, GraphQLScalarType> getBsonScalars(){
