            case "%bulk":
                bulk = "on".equals(value);
                if (!bulk) {
                    out.println(gson.toJson(game));
                }
                break;
            case "%compat":
                Version compat = Version.valueOf(value);
//                if (compat.lessThan(Version.valueOf("5.7.0"))) {
//                    compatJavaRandom = true;
//                }
                break;
            case "%load":
                tileDefinitions.add(value);
                break;
            case "%state":
                out.println(gson.toJson(game));
                break;
