        return Collections.unmodifiableSet(dateConstraints);
    }

    protected boolean checkConstraints(DateModel<?> model) {
        for (DateSelectionConstraint constraint : dateConstraints) {
            if (!constraint.isValidSelection(model)) {
                return false;
            }
        }
        return true;
