package org.enderstone.server;

import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Properties;
import java.util.Random;

import javax.imageio.ImageIO;

import org.enderstone.server.entity.EnderPlayer;
import org.enderstone.server.packet.play.PacketKeepAlive;
import org.enderstone.server.regions.EnderWorld;

public class Main implements Runnable {

	public static final String NAME = "Enderstone";
	public static final String PROTOCOL_VERSION = "1.7.6";
	public static final int PROTOCOL = 5;
	public static final String[] AUTHORS = new String[] { "bigteddy98", "ferrybig", "timbayens" };

	public BufferedImage favicon = null;
	public Properties prop = null;
	public static final Random random = new Random();
	public int port;
	public final EnderWorld mainWorld = new EnderWorld();
	public volatile boolean isRunning = true;

	private static Main instance;

	public final List<EnderPlayer> onlinePlayers = new ArrayList<>();
	private final List<Runnable> sendToMainThread = Collections.synchronizedList(new ArrayList<Runnable>());

	public Main() {
		instance = this;
	}

	public static Main getInstance() {
		return instance;
	}

	public void sendToMainThread(Runnable run) {
		synchronized (sendToMainThread) {
			sendToMainThread.add(run);
		}
	}

	public static void main(String[] args) {
		new Thread(new Main()).start();
	}

	@Override
	public void run() {
		EnderLogger.info("Starting " + NAME + " server version " + PROTOCOL_VERSION + " at port " + this.port);
		EnderLogger.info("Authors: " + Arrays.asList(AUTHORS).toString());

		EnderLogger.info("Loading config.ender");
		this.loadConfigFromDisk();

		EnderLogger.info("Loading favicon.");
		try {
			BufferedImage image = ImageIO.read(new File("server-icon.png"));
			if (image.getWidth() == 64 && image.getHeight() == 64) {
				favicon = image;
			} else {
				EnderLogger.exception(new IllegalArgumentException(
						"Your server-icon.ping needs to be 64*64!"));
			}
		} catch (IOException e) {
			EnderLogger.exception(new FileNotFoundException(
					"server-icon.png not found!"));
		}

		EnderLogger.info("Starting Netty Server...");

		new Thread(new Runnable() {

			@Override
			public void run() {
				EnderLogger.info("Netty Server Started!");

				EventLoopGroup bossGroup = new NioEventLoopGroup();
				EventLoopGroup workerGroup = new NioEventLoopGroup();

				try {
					ServerBootstrap bootstrap = new ServerBootstrap();
					bootstrap.group(bossGroup, workerGroup);
					bootstrap.channel(NioServerSocketChannel.class);
					bootstrap.childHandler(new MinecraftServerInitializer());

					bootstrap.bind(port).sync().channel().closeFuture().sync();
				} catch (InterruptedException e) {
					e.printStackTrace();
				} finally {
					bossGroup.shutdownGracefully();
					workerGroup.shutdownGracefully();
				}
			}
		}).start();

		EnderLogger.info("Initializing main Server Thread...");
		new Thread(new Runnable() {

			@Override
			public void run() {
				while (isRunning) {
					synchronized (sendToMainThread) {
						for (Runnable run : sendToMainThread) {
							try {
								run.run();
							} catch (Exception e) {
								e.printStackTrace();
							}
						}
						sendToMainThread.clear();
					}

					try {
						serverTick();
					} catch (Exception e1) {
						e1.printStackTrace();
					}

					try {
						Thread.sleep(50L);
					} catch (InterruptedException e) {
						e.printStackTrace();
					}
				}
			}
		}).start();
		EnderLogger.info("Main Server Thread initialized and started!");
		EnderLogger.info(NAME + " Server started, " + PROTOCOL_VERSION + " clients can now connect to port " + this.port + "!");
	}

	public void saveConfigToDisk(boolean defaultt) {
		try {
			OutputStream output = new FileOutputStream("config.ender");
			if (defaultt) {
				prop.setProperty("motd", "Another Enderstone server!");
				prop.setProperty("port", "25565");
				prop.setProperty("max-players", "20");
				prop.setProperty("view-distance", "7");
			}
			prop.store(output, "Enderstone Server Config!");
		} catch (IOException e1) {
			EnderLogger.exception(e1);
		}
	}

	public Properties loadConfigFromDisk() {
		InputStream input;
		prop = new Properties();
		try {
			input = new FileInputStream("config.ender");
			prop.load(input);
			port = Integer.parseInt(prop.getProperty("port"));
		} catch (FileNotFoundException e) {
			this.saveConfigToDisk(true);
		} catch (IOException e) {
			EnderLogger.exception(e);
		}
		return prop;
	}

	public EnderPlayer getPlayer(String name) {
		for (EnderPlayer ep : this.onlinePlayers) {
			if (ep.getPlayerName().equals(name)) {
				return ep;
			}
		}
		return null;
	}

	private int latestKeepAlive = 0;
	private int latestChunkUpdate = 0;

	private void serverTick() throws Exception {
		if ((latestKeepAlive++ & 0b1111111) == 0) { // faster than % .. == 0
			for (EnderPlayer p : onlinePlayers) {
				p.getNetworkManager().sendPacket(new PacketKeepAlive(p.keepAliveID = random.nextInt(Integer.MAX_VALUE)));
			}
		}

		if ((latestChunkUpdate++ & 0b111111) == 0) { // faster than % .. == 0
			for (EnderPlayer p : onlinePlayers) {
				mainWorld.doChunkUpdatesForPlayer(p, p.chunkInformer, 10);
				p.updatePlayers(onlinePlayers);
			}
		}
	}
}

package org.enderstone.server.packet;

import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.channel.ChannelHandlerContext;
import io.netty.handler.codec.ReplayingDecoder;

import java.util.List;

import org.enderstone.server.EnderLogger;
import org.enderstone.server.Main;
import org.enderstone.server.entity.EnderPlayer;
import org.enderstone.server.packet.NetworkManager.Stage;
import org.enderstone.server.packet.login.PacketInLoginStart;
import org.enderstone.server.packet.play.PacketInChatMessage;
import org.enderstone.server.packet.play.PacketInClientSettings;
import org.enderstone.server.packet.play.PacketInPlayerDigging;
import org.enderstone.server.packet.play.PacketInPlayerLook;
import org.enderstone.server.packet.play.PacketInPlayerPosition;
import org.enderstone.server.packet.play.PacketInPlayerPositionLook;
import org.enderstone.server.packet.play.PacketInPluginMessage;
import org.enderstone.server.packet.play.PacketKeepAlive;
import org.enderstone.server.packet.play.PacketOutEntityDestroy;
import org.enderstone.server.packet.status.PacketInRequest;
import org.enderstone.server.packet.status.PacketPing;

public class NetworkManager extends ReplayingDecoder<Stage> {

	private ChannelHandlerContext ctx;
	private Channel channel;
	EnderPlayer player;
	private PacketReciever packetReciever;

	int handShakeStatus = -1;
	private int length;

	// private List<Packet> waitingPackets = Collections.synchronizedList(new
	// ArrayList<Packet>());

	PacketHandshake lastHandshake = null;

	public NetworkManager() {
		super(Stage.LENGTH);
		this.packetReciever = new PacketReciever(this);
	}

	@Override
	protected void decode(ChannelHandlerContext ctx, ByteBuf buf, List<Object> args) throws Exception {

		if (this.channel == null) {
			this.channel = ctx.channel();
		}
		if (this.ctx == null) {
			this.ctx = ctx;
		}

		if (this.state() == Stage.LENGTH) {
			this.length = Packet.readVarInt(buf);
			this.checkpoint(Stage.DATA);
		} else if (this.state() == Stage.DATA) {
			buf.markReaderIndex();
			buf.readBytes(this.length);
			buf.resetReaderIndex();

			int id = Packet.readVarInt(buf);

			if (handShakeStatus == -1) {
				PacketHandshake packet = (PacketHandshake) PacketManager.handshake.newInstance();
				packet.read(buf);
				this.handShakeStatus = packet.getNextState();
			} else if (handShakeStatus == 1) {
				Packet packet = PacketManager.getPacket(this, id, HandshakeState.STATUS).newInstance();
				packet.read(buf);
				this.onPacketRecieve(packet);
			} else if (handShakeStatus == 2) {
				Packet packet = PacketManager.getPacket(this, id, HandshakeState.LOGIN).newInstance();
				packet.read(buf);
				this.onPacketRecieve(packet);
			} else if (handShakeStatus == 3) {
				Packet packet = PacketManager.getPacket(this, id, HandshakeState.PLAY).newInstance();
				packet.read(buf);
				this.onPacketRecieve(packet);
			}
			this.state(Stage.LENGTH);
		}
	}

	private void onPacketRecieve(Packet packet) throws Exception {

		// System.out.println("Recieved " + packet.getClass().getSimpleName() +
		// " with id 0x" + Integer.toHexString(packet.getId()));

		if (packet instanceof PacketInRequest) {
			this.packetReciever.packetInRequest((PacketInRequest) packet, lastHandshake);
			lastHandshake = null;
		} else if (packet instanceof PacketPing) {
			this.packetReciever.packetPing((PacketPing) packet);
		} else if (packet instanceof PacketInLoginStart) {
			this.packetReciever.packetInLoginStart((PacketInLoginStart) packet);
		} else if (packet instanceof PacketInClientSettings) {
			this.packetReciever.packetInClientSettings((PacketInClientSettings) packet);
		} else if (packet instanceof PacketInPluginMessage) {
			this.packetReciever.packetInPluginMessage((PacketInPluginMessage) packet);
		}

		else if (packet instanceof PacketInPlayerPositionLook) {
			this.packetReciever.packetInPlayerPositionLook((PacketInPlayerPositionLook) packet);
		} else if (packet instanceof PacketInPlayerPosition) {
			this.packetReciever.packetInPlayerPosition((PacketInPlayerPosition) packet);
		}

		else if (packet instanceof PacketKeepAlive) {
			this.packetReciever.packetKeepAlive((PacketKeepAlive) packet);
		} else if (packet instanceof PacketInChatMessage) {
			this.packetReciever.packetInChatMessage((PacketInChatMessage) packet);
		} else if (packet instanceof PacketInPlayerDigging) {
			this.packetReciever.packetInPlayerDigging((PacketInPlayerDigging) packet);
		} else if (packet instanceof PacketInPlayerLook) {
			this.packetReciever.packetInPlayerLook((PacketInPlayerLook) packet);
		}
	}

	@Override
	public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
		this.channelInactive(ctx);
		super.exceptionCaught(ctx, cause);
	}

	@Override
	public void channelInactive(ChannelHandlerContext ctx) throws Exception {
		if (player != null) {
			Main.getInstance().sendToMainThread(new Runnable() {

				@Override
				public void run() {
					try {
						player.onDisconnect();
					} catch (Exception e) {
						e.printStackTrace();
					}
					if (Main.getInstance().onlinePlayers.contains(player)) {
						Main.getInstance().onlinePlayers.remove(player);

						for (EnderPlayer ep : Main.getInstance().onlinePlayers) {
							for (String name : ep.visiblePlayers) {
								if (name.equals(player.getPlayerName()) && !player.getPlayerName().equals(ep.getPlayerName())) {
									try {
										ep.getNetworkManager().sendPacket(new PacketOutEntityDestroy(new Integer[] { player.getEntityId() }));
									} catch (Exception e) {
										e.printStackTrace();
									}
								}
							}
						}
					}
				}
			});
		}
		super.channelInactive(ctx);
	}

	enum Stage {
		LENGTH, DATA
	}

	public synchronized void sendPacket(Packet... packets) throws Exception {
		ByteBuf buf = Unpooled.buffer();
		for (Packet packet : packets) {
			EnderLogger.debug(packet.toString());
			Packet.writeVarInt(packet.getSize(), buf);
			Packet.writeVarInt(packet.getId(), buf);
			packet.write(buf);
		}
		this.channel.writeAndFlush(buf);
	}
}

