		builder.add(method(returnType, name)
				.annotation("@Override")
				.modifier(
						method.getModifiers()
								& ~(Modifier.NATIVE | Modifier.ABSTRACT))
				.arguments(arguments).commandBlock(sb.toString())
				.exceptions(method.getExceptionTypes()));
	}

