	private void importKey(APDU apdu) {
		short offset = 0;

		if (!pw3.isValidated())
			ISOException.throwIt(SW_SECURITY_STATUS_NOT_SATISFIED);

		// Check for tag 4D
		if (buffer[offset++] != 0x4D)
