		key.setPQ(buffer, offset_data, len_pq);
		offset_data += len_pq;

		key.setDP1(buffer, offset_data, len_dp1);
		offset_data += len_dp1;

		key.setDQ1(buffer, offset_data, len_dq1);
		offset_data += len_dq1;

		key.setModulus(buffer, offset_data, len_modulus);
		offset_data += len_modulus;
