		doVerify("12345678", (byte) 0x83, State.GOOD);
		assertArrayEquals(success, simulator.transmitCommand(newRc));
		simulator.reset();
		simulator.selectApplet(aid);

		assertArrayEquals(new byte[] {3, 3, 3}, getPinRetries());
